<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard Admin - ONAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f8f9fa}.sidebar{min-height:100vh;background:#212529;color:#fff;position:fixed;width:250px}.sidebar a{color:#adb5bd;text-decoration:none;padding:12px 20px;display:block}.sidebar a:hover{color:#fff;background:#0d6efd}.main-content{margin-left:250px;padding:30px}.table-img{width:50px;height:50px;object-fit:cover;border-radius:6px}</style></head><body><div class="sidebar p-3"><h3 class="text-center text-white mb-4">ONAS Admin</h3><a href="index.php?action=dashboard_admin">Tableau de bord</a><a href="index.php?action=liste_citoyens">Gestion Citoyens</a><a href="index.php?action=gestion_equipe">Gestion Équipes</a><hr><form action="index.php?action=logout" method="POST"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><button type="submit" class="btn btn-outline-danger">Déconnexion</button></form></div><div class="main-content"><?php $equipes=$equipes??[];$filter=$_GET['filter']??'tous';$reclamations=$reclamations??[];$filtered=array_filter($reclamations,function($r)use($filter){if($filter==='attente'&&($r['statut']??'')!=='En attente')return false;if($filter==='cours'&&($r['statut']??'')!=='En cours')return false;if($filter==='terminee'&&!in_array($r['statut']??'', ['Terminée','Traité'],true))return false;return true;});?><div class="row mb-4"><div class="col"><div class="card bg-primary text-white p-3"><h6>Total</h6><h2><?=count($reclamations)?></h2></div></div><div class="col"><div class="card bg-warning p-3"><h6>En attente</h6><h2><?=count(array_filter($reclamations,fn($r)=>($r['statut']??'')==='En attente'))?></h2></div></div><div class="col"><div class="card bg-success text-white p-3"><h6>Terminées</h6><h2><?=count(array_filter($reclamations,fn($r)=>in_array($r['statut']??'', ['Terminée','Traité'],true)))?></h2></div></div></div><div class="card p-4"><h4>Suivi des Réclamations</h4><div class="table-responsive"><table class="table align-middle"><thead class="table-dark"><tr><th>ID</th><th>Citoyen</th><th>Problème</th><th>Repère</th><th>Photo</th><th>Statut</th><th>Affectation</th><th>Actions</th></tr></thead><tbody><?php if($filtered):foreach($filtered as $r):$id=(int)$r['id_reclamation'];$done=in_array($r['statut']??'', ['Terminée','Traité'],true);?><tr><td>#<?=$id?></td><td><?=htmlspecialchars($r['nom_citoyen']??'Inconnu',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['type_probleme']??'',ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['repere']??'',ENT_QUOTES,'UTF-8')?><?php if(!empty($r['latitude'])&&!empty($r['longitude'])):?><br><a href="https://www.google.com/maps?q=<?=rawurlencode((string)$r['latitude'])?>,<?=rawurlencode((string)$r['longitude'])?>" target="_blank" rel="noopener noreferrer">GPS</a><?php endif;?></td><td><?php if(!empty($r['photo'])):?><img src="<?=htmlspecialchars($r['photo'],ENT_QUOTES,'UTF-8')?>" class="table-img" alt="Photo"><?php endif;?></td><td><?=htmlspecialchars($r['statut']??'',ENT_QUOTES,'UTF-8')?></td><td><form action="index.php?action=affecter" method="POST" class="d-flex"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id_reclamation" value="<?=$id?>"><select name="id_equipe" class="form-select form-select-sm" <?=$done?'disabled':'required'?>><option value="">Équipe...</option><?php foreach($equipes as $eq):$eid=(int)$eq['id_employer'];?><option value="<?=$eid?>" <?=($r['affecte_a']??'')==$eid?'selected':''?>><?=htmlspecialchars($eq['nom']??'',ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select><?php if(!$done):?><button class="btn btn-success btn-sm">OK</button><?php endif;?></form></td><td><button class="btn btn-info btn-sm" data-bs-toggle="modal" data-bs-target="#m<?=$id?>">Voir</button><form action="index.php?action=supprimer" method="POST" class="d-inline" onsubmit="return confirm('Confirmer ?')"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="id" value="<?=$id?>"><button class="btn btn-danger btn-sm">Supprimer</button></form></td></tr><div class="modal fade" id="m<?=$id?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h5>Détails #<?=$id?></h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><p><?=!empty($r['rapport'])?nl2br(htmlspecialchars($r['rapport'],ENT_QUOTES,'UTF-8')):'Aucun rapport.'?></p><?php if(!empty($r['photo_intervention'])):?><img src="<?=htmlspecialchars($r['photo_intervention'],ENT_QUOTES,'UTF-8')?>" class="img-fluid" alt="Intervention"><?php endif;?></div></div></div></div><?php endforeach;else:?><tr><td colspan="8" class="text-center">Aucune réclamation.</td></tr><?php endif;?></tbody></table></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js"></script></body></html>